pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockNum, uint256 warpTime) public {
        // Restrict msg.value to a wide range around the changed require
        vm.assume(value <= 20 ether && value >= 1 ether);
        // Ensure warpTime is in a reasonable future range
        vm.assume(warpTime > block.timestamp && warpTime < type(uint256).max);
        // Ensure block.number after future warp is reasonable
        vm.assume(blockNum > block.number && blockNum < type(uint256).max);

        vm.deal(address(this), value);
        vm.warp(warpTime);
        vm.roll(blockNum);

        bool ok;
        try c.fallback{value: value}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Invariant: if the call succeeded, the contract balance must be 0
        // (because a successful fallback transfers the entire balance when block.number % 15 == 0,
        // but the reference only succeeds with exactly 10 ether, which then must be transferred
        // if block.number % 15 == 0. If block.number % 15 != 0 and 10 ether is sent,
        // the balance remains but the invariant holds: revert path doesn't apply.
        // Actually, correct invariant: after any NON-reverting fallback, the balance is 0.
        // The bug allows a 9 ether call to succeed; when block.number % 15 != 0, balance stays 9 ether, breaking invariant.
        assertTrue(!ok || address(c).balance == 0);
    }
}

