pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint64 blockNumber, uint64 timestamp, uint8 callCount) public {
        // Bound callCount to a reasonable range for fuzzer exploration (1 to 20)
        uint8 boundedCalls = uint8(bound(uint256(callCount), 1, 20));
        vm.assume(blockNumber > 0);
        vm.assume(timestamp > 0);

        // Set block context
        vm.roll(blockNumber);
        vm.warp(timestamp);

        // Record balance before any calls
        uint256 balanceBefore = address(c).balance;
        uint256 totalSent = 0;

        address sender = makeAddr("sender");
        vm.deal(sender, 1000 ether);
        vm.startPrank(sender);

        for (uint8 i = 0; i < boundedCalls; i++) {
            // Each call sends 10 ether
            c.f{value: 10 ether}();
        }

        vm.stopPrank();

        // After all calls in the same block, compute how much was actually transferred out
        uint256 balanceAfter = address(c).balance;
        uint256 totalDeposited = uint256(boundedCalls) * 10 ether;
        totalSent = balanceBefore + totalDeposited - balanceAfter;

        // If block number isn't a multiple of 15, no transfer should have occurred.
        // The invariant: if block.number % 15 != 0, totalSent == 0.
        if (blockNumber % 15 != 0) {
            assertTrue(totalSent == 0);
        }
    }
}

