pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp) public {
        // Restrict to admissible domain: block number positive, timestamp >= 1
        vm.assume(blockNum > 0);
        vm.assume(timestamp >= 1);
        // Set block number and timestamp
        vm.roll(blockNum);
        vm.warp(timestamp);
        // Fund the test contract itself to act as caller
        vm.deal(address(this), 20 ether);
        // Record balance before first call
        uint256 balBefore = address(c).balance;
        // Make first call with 10 ether
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");
        // Make second call in the SAME block (no warp, no roll change) with additional 10 ether
        (bool ok2,) = address(c).call{value: 10 ether}("");
        // If the second call succeeds, the mutant may have allowed the transfer logic to alter the balance.
        // The reference contract requires block.timestamp > pastBlockTime, so it will revert the second call.
        // After both calls, the contract's balance must equal balBefore + 10 ether (first call only).
        // The mutant, by removing the timestamp check, allows the second call, and if block.number % 15 == 0,
        // it also transfers the entire balance, changing the expected balance.
        assertTrue(address(c).balance == balBefore + 10 ether);
    }
}

