pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber1, uint256 blockNumber2) public {
        // Restrict block numbers to a manageable range and make them distinct
        bound(blockNumber1, 1, type(uint64).max);
        bound(blockNumber2, 1, type(uint64).max);
        vm.assume(blockNumber1 != blockNumber2);

        // Ensure the first call succeeds; set block.timestamp to a sane value and give enough ether
        vm.roll(blockNumber1);
        vm.warp(1000);
        vm.deal(address(this), 10 ether);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        uint256 firstPast = c.pastBlockTime();

        // Second call in the same block (same timestamp) should revert on reference, but will succeed on mutant
        vm.roll(blockNumber2);
        // block.timestamp not changed -> same timestamp as first call
        vm.deal(address(this), 10 ether);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        uint256 secondPast = c.pastBlockTime();

        // Reference: ok2 is false, pastBlockTime unchanged (secondPast == firstPast)
        // Mutant: ok2 is true, pastBlockTime updated (secondPast == firstPast still, but state changed)
        // The invariant: pastBlockTime must be strictly greater after a successful call
        // If ok2 succeeded, secondPast must be > firstPast; if it failed, we cannot assert on pastBlockTime increase
        // Instead, assert: ok2 implies secondPast > firstPast
        assertTrue(!ok2 || secondPast > firstPast);
    }
}

