// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime, address sender, uint256 initialFunds) public {
        // Keep block number in a wide admissible range, excluding 0 to avoid underflow in modulo check.
        vm.assume(blockNum > 0);
        // Warp time must be > 0 so that block.timestamp > pastBlockTime (which starts at 0) holds.
        vm.assume(warpTime > 0);
        // Sender must be distinct from the test contract and the C contract itself.
        vm.assume(sender != address(this) && sender != address(c));
        // Provide the contract with a base balance so transfers are possible.
        // Use at least 1 wei + exactly 10 ether required for msg.value.
        initialFunds = bound(initialFunds, 1, 1000 ether);
        vm.deal(address(c), initialFunds);

        // Ensure the fallback call succeeds with exactly 10 ether.
        vm.deal(sender, 10 ether);
        vm.warp(warpTime);
        vm.roll(blockNum);

        // Record balance before the fallback call.
        uint256 balBefore = address(c).balance;

        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "fallback call reverted unexpectedly");

        uint256 balAfter = address(c).balance;

        if (blockNum % 15 == 0) {
            // For blocks divisible by 15, both reference and mutant transfer the full balance.
            assertEq(balAfter, 0);
        } else {
            // For blocks NOT divisible by 15, the reference retains all funds (balance increases by 10 ether),
            // while the mutant transfers everything, leaving balance 0.
            assertEq(balAfter, balBefore + 10 ether);
        }
    }
}
